 13	void timer_create(TimerCallback func, void* parameter, uint64_t tick)
 14	{
 15	    disable_preempt();
 16	
 17	    list_add_tail(&current_running[cpu_id]->timer.list, &timer_queue);
 18	    current_running[cpu_id]->timer.timeout_tick = tick;
 19	    current_running[cpu_id]->timer.callback_func = func;
 20	    current_running[cpu_id]->timer.parameter = parameter;
 21	
 22	    enable_preempt();
 23	}
