 25	/* check all timers. if timeouts, call callback_func and free the timer */
 26	void timer_check()
 27	{
 28	    disable_preempt();
 29	
 30	    uint64_t current_tick = get_ticks();
 31	    list_node_t* p = timer_queue.next;
 32	
 33	    while(p != &timer_queue){
 34	        timer_t *timer_node = list_entry(p, timer_t, list);
 35	        if(current_tick >= timer_node->timeout_tick){
 36	            (timer_node->callback_func)(timer_node->parameter);
 37	            p = p->next;
 38	            list_del(p->prev);
 39	        }
 40	        else{
 41	            p = p->next;
 42	        } 
 43	    }
 44	
 45	    enable_preempt();
 46	}
