 9	static int binsem_hash(uint64_t x)
10	{
11	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
12	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
13	    x = x ^ (x >> 31);
14	    return x % BINSEM_NUMBER;
15	}
