 72	#define _PAGE_PRESENT (1 << 0)
 73	#define _PAGE_READ (1 << 1)     /* Readable */
 74	#define _PAGE_WRITE (1 << 2)    /* Writable */
 75	#define _PAGE_EXEC (1 << 3)     /* Executable */
 76	#define _PAGE_USER (1 << 4)     /* User */
 77	#define _PAGE_GLOBAL (1 << 5)   /* Global */
 78	#define _PAGE_ACCESSED (1 << 6) /* Set by hardware/software on any access */
 79	#define _PAGE_DIRTY (1 << 7)    /* Set by hardware/software on any write */
 80	#define _PAGE_SOFT (1 << 8)     /* Reserved for software */
 81	#define _PAGE_PFN_SHIFT 10lu
 82	
 83	#define VA_MASK ((1lu << 39) - 1)
 84	#define PFN_MASK ((1lu << 44) - 1)
 85	#define ATTRIBUTE_MASK ((1lu << 9) - 1)
 86	#define PAGE_OFFSET_MASK ((1lu << 12) - 1)
 87	
 88	#define PPN_BITS 9lu
 89	#define NUM_PTE_ENTRY (1 << PPN_BITS)
 90	#define PPN_MASK ((1lu << PPN_BITS) - 1)
 91	#define VPN_MASK ((1lu << PPN_BITS) - 1)
 92	
 93	#define KERNEL_MEM_OFFSET 0xffffffc000000000
 94	
 95	#define VPN2_SHIFT 30
 96	#define VPN1_SHIFT 21
 97	#define VPN0_SHIFT 12
 98	
 99	typedef uint64_t PTE;
100	
101	static inline void clear_pgdir(PTE* pgdir_addr)
102	{
103	    memset(pgdir_addr, 0, 4096);
104	}
105	
106	/* Get/Set page frame number of the `entry` */
107	static inline long get_pfn(PTE entry)
108	{
109	    return ((entry >> _PAGE_PFN_SHIFT) & PFN_MASK);
110	}
111	static inline void set_pfn(PTE *entry, uint64_t pfn)
112	{
113	    *entry = *entry & ATTRIBUTE_MASK;
114	    *entry = *entry | (pfn << _PAGE_PFN_SHIFT);
115	}
116	static inline uintptr_t get_pa(PTE entry)
117	{
118	    return (((entry >> _PAGE_PFN_SHIFT) & PFN_MASK) << NORMAL_PAGE_SHIFT);
119	}
120	
121	/* Get/Set/Clear attribute(s) of the `entry` */
122	static inline long get_attribute(PTE entry, uint64_t mask)
123	{
124	    return ((entry & mask) != 0);
125	}
126	static inline void set_attribute(PTE *entry, uint64_t bits)
127	{
128	    *entry = *entry | bits;
129	}
130	static inline void clear_attribute(PTE *entry, uint64_t bits)
131	{
132	    *entry = *entry & ~bits;
133	}
134	
135	static inline uintptr_t kva2pa(uintptr_t kva)
136	{
137	    return (uintptr_t)(kva - KERNEL_MEM_OFFSET);
138	}
139	static inline uintptr_t pa2kva(uintptr_t pa)
140	{
141	    return (uintptr_t)(pa + KERNEL_MEM_OFFSET);
142	}
143	
144	// pgdir is pa
145	static inline uintptr_t get_kva_of(uintptr_t va, uintptr_t pgdir)
146	{
147	    uintptr_t pgdir_kva = pa2kva((uintptr_t)pgdir);
148	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
149	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
150	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
151	
152	    PTE* second_level_pgdir = (PTE*)get_pa((uintptr_t)*((PTE*)pgdir_kva + VPN2));
153	    second_level_pgdir = (PTE*)pa2kva((uintptr_t)second_level_pgdir);
154	    PTE* last_level_pgdir = (PTE*)get_pa((uintptr_t)*((PTE*)second_level_pgdir + VPN1));
155	    last_level_pgdir = (PTE*)pa2kva((uintptr_t)last_level_pgdir);
156	    uintptr_t pa = get_pa((uintptr_t)*((PTE*)last_level_pgdir + VPN0)) | (va & PAGE_OFFSET_MASK);
157	    return pa2kva(pa);
158	}
