    18	// a simple hash function
    19	static int futex_hash(uint64_t x)
    20	{
    21	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
    22	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
    23	    x = x ^ (x >> 31);
    24	    return x % FUTEX_BUCKETS;
    25	}
    26	
    27	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
    28	{
    29	    int key = futex_hash((uint64_t)val_addr);
    30	    list_node_t *head = &futex_buckets[key];
    31	    for (list_node_t *p = head->next; p != head; p = p->next) {
    32	        futex_node_t *node = list_entry(p, futex_node_t, list);
    33	        if (node->futex_key == (uint64_t)val_addr) {
    34	            return node;
    35	        }
    36	    }
    37	
    38	    if (create) {
    39	        futex_node_t *node = (futex_node_t*)pa2kva((uintptr_t)kmalloc(sizeof(futex_node_t)));
    40	        node->futex_key = (uint64_t)val_addr;
    41	        init_list_head(&node->block_queue);
    42	        list_add_tail(&node->list, &futex_buckets[key]);
    43	        return node;
    44	    }
    45	
    46	    return NULL;
    47	}
    48	
    49	void futex_wait(volatile uint64_t *val_addr, int binsem_id)
    50	{
    51	    disable_preempt();
    52	
    53	    futex_node_t *node = get_node(val_addr, 1);
    54	    assert(node != NULL);
    55	    do_block(&current_running[cpu_id]->list, &node->block_queue);
    56	    binsem_op(binsem_id, BINSEM_OP_UNLOCK);
    57	    scheduler(); 
    58	
    59	    enable_preempt();
    60	}
    61	
    62	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
    63	{
    64	    disable_preempt();
    65	    futex_node_t *node = get_node(val_addr, 0);
    66	
    67	    if (node != NULL) {
    68	        for (int i = 0; i < num_wakeup; ++i) {
    69	            if (list_empty(&node->block_queue)) break;
    70	
    71	            do_unblock(node->block_queue.next);
    72	        }
    73	    }
    74	
    75	    scheduler();
    76	    enable_preempt();
